package main

// Purpose: `nself ci providers gitlab init [--check] [--stdout] [--untrusted-dir <dir> [--inputs]]
// [--dir <repo>] [--json]` (P7-HOST-06, Epic D11): render the GitLab include file from templates/gitlab,
// write it to <repo>/.gitlab/nself-ci.gitlab-ci.yml (or stdout), write the two generated files of the
// untrusted ref into a directory, or check that the default branch copy and the untrusted ref (both of
// its files) in local git still equal the rendering. It also links the GitLab dispatch provider and the
// GitLab status adapter into the binary (their init() registers them).
// Inputs:  argv after the key; the pinned agent commit of templates/gitlab; local git.
// Outputs: the file, or its text on stdout, or a per-file report with the exact commands that create or
//          update the untrusted ref (never run here); one v1 JSON envelope with --json.
// Constraints: V15 only; side-effect class: writes one local file and nothing else, never pushes, never
//          calls the network; an existing file that is not generated (no marker) is never overwritten;
//          git runs through the CI command funnel (report.Capture); exit 0 ok, 1 drift or refusal, 2
//          usage (the shared usage helper returns 1, as for every providers subcommand).

import (
	"context"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/nself-org/cli/sdk/go/v2/output"

	"github.com/nself-org/plugins/free/ci/internal/providers/gitlab/pipeline"
	_ "github.com/nself-org/plugins/free/ci/internal/providers/gitlab/status" // registers the GitLab commit-status reporter
	"github.com/nself-org/plugins/free/ci/internal/report"
	gitlabtmpl "github.com/nself-org/plugins/free/ci/templates/gitlab"
)

type gitlabInitFlags struct {
	check, stdout, json, inputs bool
	dir, untrustedDir           string
}

func newGitlabInitFlags(f *gitlabInitFlags) *flag.FlagSet {
	fs := flag.NewFlagSet("providers gitlab init", flag.ContinueOnError)
	fs.BoolVar(&f.check, "check", false, "compare the default-branch and untrusted-ref copies in local git with the rendering")
	fs.BoolVar(&f.stdout, "stdout", false, "print the include file instead of writing it")
	fs.StringVar(&f.dir, "dir", "", "repository root (env NSELF_CI_REPO; default: current directory)")
	fs.StringVar(&f.untrustedDir, "untrusted-dir", "", "write the two generated files of the untrusted ref into this directory")
	fs.BoolVar(&f.inputs, "inputs", false, "with --untrusted-dir: the root declares pipeline inputs (GitLab 17.10+) instead of using variables")
	fs.BoolVar(&f.json, "json", false, "print one v1 JSON envelope")
	return fs
}

func init() {
	registerV15("providers gitlab init", subcommandEntry{V15Only: true, Handler: runGitlabInit,
		Flags: func() *flag.FlagSet { return newGitlabInitFlags(&gitlabInitFlags{}) }})
}

func gitlabInitFail(f gitlabInitFlags, code string, err error) int {
	if f.json {
		_ = output.WriteError(os.Stdout, "ci providers gitlab init", output.ErrorDetail{Code: code, Message: err.Error(), ExitCode: 1}, nil)
	} else {
		fmt.Fprintln(os.Stderr, "error:", err)
	}
	return 1
}

// gitlabRender renders the include file for the newest pinned agent commit.
func gitlabRender() ([]byte, string, error) {
	commits, err := gitlabtmpl.SourceCommits()
	if err != nil {
		return nil, "", fmt.Errorf("no agent commit is pinned in this build")
	}
	commit := commits[len(commits)-1]
	doc, err := gitlabtmpl.Render(gitlabtmpl.Options{AgentCommit: commit})
	return doc, commit, err
}

func runGitlabInit(args []string) int {
	var f gitlabInitFlags
	fs := newGitlabInitFlags(&f)
	if err := fs.Parse(args); err != nil || fs.NArg() != 0 || f.check && f.stdout || f.untrustedDir != "" && (f.check || f.stdout) || f.inputs && f.untrustedDir == "" {
		return usageErr("nself ci providers gitlab init [--check | --stdout | --untrusted-dir <dir> [--inputs]] [--dir <repo>] [--json]")
	}
	doc, commit, err := gitlabRender()
	if err != nil {
		return gitlabInitFail(f, "E702", err)
	}
	if f.stdout {
		_, _ = os.Stdout.Write(doc)
		return 0
	}
	if f.untrustedDir != "" {
		return gitlabUntrusted(f, doc)
	}
	root := firstOf(f.dir, os.Getenv("NSELF_CI_REPO"))
	if root == "" {
		if root, err = os.Getwd(); err != nil {
			return gitlabInitFail(f, "E702", err)
		}
	}
	if f.check {
		return gitlabCheck(context.Background(), f, root, doc)
	}
	return gitlabWrite(f, root, doc, commit)
}

// writeGenerated writes one generated file below root with the shared safety rules: an existing file
// without the GENERATED marker is never overwritten, the write is atomic and the mode is 0644.
func writeGenerated(root, rel string, doc []byte) error {
	path := filepath.Join(root, rel)
	if old, err := os.ReadFile(path); err == nil && !strings.HasPrefix(string(old), gitlabtmpl.HeaderMarker) {
		return fmt.Errorf("%s exists and is not generated by this command; move it away first", rel)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".nself-ci-gen-")
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }()
	if _, err = tmp.Write(doc); err == nil {
		err = tmp.Chmod(0o644)
	}
	if cerr := tmp.Close(); err == nil {
		err = cerr
	}
	if err == nil {
		err = os.Rename(tmp.Name(), path)
	}
	return err
}

func gitlabWrite(f gitlabInitFlags, root string, doc []byte, commit string) int {
	if err := writeGenerated(root, gitlabtmpl.Path, doc); err != nil {
		return gitlabInitFail(f, "E702", err)
	}
	if f.json {
		_ = output.WriteData(os.Stdout, "ci providers gitlab init", map[string]any{"path": gitlabtmpl.Path, "template": gitlabtmpl.Current,
			"agent_commit": commit, "untrusted_ref": pipeline.DefaultUntrustedRef}, nil)
		return 0
	}
	fmt.Printf("wrote %s (template v%d, agent commit %s)\n", gitlabtmpl.Path, gitlabtmpl.Current, commit[:12])
	fmt.Printf("next: add `include: [{local: %s}]` to .gitlab-ci.yml, commit both to the default branch,\n", gitlabtmpl.Path)
	fmt.Printf("      then run: nself ci providers gitlab init --check (it prints how to create the untrusted ref %s)\n", pipeline.DefaultUntrustedRef)
	fmt.Printf("notes: the values travel as pipeline variables; for GitLab 17.10+ pipeline inputs copy the snippet in the file header\n")
	fmt.Printf("       into .gitlab-ci.yml. Keep protected CI/CD variables out of this project: the default-branch pipeline can read them.\n")
	return 0
}

// gitlabUntrusted writes the whole file set of the untrusted ref: the generated root (variables, or
// inputs with --inputs) and the include file. The ref holds exactly these two files, which the
// coordinator compares byte for byte at the commit a pipeline ran on.
func gitlabUntrusted(f gitlabInitFlags, include []byte) int {
	kind := gitlabtmpl.RootVariables
	if f.inputs {
		kind = gitlabtmpl.RootInputs
	}
	for _, file := range []struct {
		rel string
		doc []byte
	}{{gitlabtmpl.RootPath, gitlabtmpl.RenderRoot(kind)}, {gitlabtmpl.Path, include}} {
		if err := writeGenerated(f.untrustedDir, file.rel, file.doc); err != nil {
			return gitlabInitFail(f, "E702", err)
		}
	}
	if f.json {
		_ = output.WriteData(os.Stdout, "ci providers gitlab init", map[string]any{"dir": f.untrustedDir, "root": kind,
			"files": []string{gitlabtmpl.RootPath, gitlabtmpl.Path}}, nil)
		return 0
	}
	fmt.Printf("wrote %s and %s (%s root) into %s\n", gitlabtmpl.RootPath, gitlabtmpl.Path, kind, f.untrustedDir)
	return 0
}

func gitlabShow(ctx context.Context, root, ref, path string) (string, bool) {
	out, exit, err := report.Capture(ctx, "git", "-c", "core.fsmonitor=false", "-C", root, "show", ref+":"+path)
	return out, err == nil && exit == 0
}

// gitlabCheck compares the include file on the default branch, and both generated files on the untrusted
// ref, as local git has them, with the rendering (githubCopy is the shared per-file result type). The
// untrusted root is ok when it is either generated variant.
func gitlabCheck(ctx context.Context, f gitlabInitFlags, root string, doc []byte) int {
	def, untrusted := defaultRemoteBranch(ctx, root), pipeline.DefaultUntrustedRef
	judge := func(ref, path string, ok func(string) bool) githubCopy {
		status := "ok"
		switch got, found := gitlabShow(ctx, root, ref, path); {
		case !found:
			status = "missing"
		case !ok(got):
			status = "drifted"
		}
		return githubCopy{Ref: ref + ":" + path, Status: status}
	}
	same := func(s string) bool { return s == string(doc) }
	copies := []githubCopy{
		judge("origin/"+def, gitlabtmpl.Path, same),
		judge("origin/"+untrusted, gitlabtmpl.Path, same),
		judge("origin/"+untrusted, gitlabtmpl.RootPath, func(s string) bool { return gitlabtmpl.RootKindOf([]byte(s)) != "" }),
	}
	var bad []string
	for _, c := range copies {
		if c.Status != "ok" {
			bad = append(bad, c.Ref)
		}
	}
	if f.json {
		_ = output.WriteData(os.Stdout, "ci providers gitlab init", map[string]any{"copies": copies, "ok": len(bad) == 0}, nil)
	} else {
		fmt.Println("(local git as it is: run `git fetch origin` first)")
		for _, c := range copies {
			fmt.Printf("%-64s %s\n", c.Ref, c.Status)
		}
		gitlabFixes(copies, def, untrusted)
	}
	if len(bad) > 0 {
		fmt.Fprintf(os.Stderr, "error: %s %s the rendering\n", strings.Join(bad, ", "), map[bool]string{true: "differ from", false: "differs from"}[len(bad) > 1])
		return 1
	}
	return 0
}

// gitlabFixes prints what the operator runs to bring the copies in line (nothing here runs them). The
// untrusted ref is an orphan commit of exactly the two generated files; it must stay unprotected and the
// project must hold no protected CI/CD variables, because the coordinator dispatches untrusted work there.
func gitlabFixes(copies []githubCopy, def, untrusted string) {
	if copies[0].Status != "ok" {
		fmt.Printf("\nthe default branch copy is %s: run nself ci providers gitlab init, commit %s and push it to %s\n", copies[0].Status, gitlabtmpl.Path, def)
		return
	}
	if copies[1].Status == "ok" && copies[2].Status == "ok" {
		return
	}
	fmt.Printf("\nthe untrusted ref must be an orphan commit of exactly the two generated files (add --inputs for GitLab 17.10+ pipeline inputs).\nCreate or update it, and keep it unprotected:\n")
	fmt.Printf("  url=$(git remote get-url origin) && d=$(mktemp -d) && nself ci providers gitlab init --untrusted-dir \"$d\" \\\n")
	fmt.Printf("    && git -C \"$d\" init -q && git -C \"$d\" add -A \\\n")
	fmt.Printf("    && git -C \"$d\" -c user.name=nself-ci -c user.email=nself-ci@localhost commit -qm 'nself ci untrusted ref' \\\n")
	fmt.Printf("    && git -C \"$d\" push --force \"$url\" HEAD:refs/heads/%s && rm -rf \"$d\"\n", untrusted)
}
